"209 :     protected Dfp(final DfpField field, long x) {
210 : 
211 :         // initialize as if 0
212 :         mant = new int[field.getRadixDigits()];
213 :         nans = FINITE;
214 :         this.field = field;
215 : 
216 :         boolean isLongMin = false;
217 :         if (x == Long.MIN_VALUE) {
218 :             // special case for Long.MIN_VALUE (-9223372036854775808)
219 :             // we must shift it before taking its absolute value
220 :             isLongMin = true;
221 :             ++x;
222 :         }
223 : 
224 :         // set the sign
225 :         if (x < 0) {
226 :             sign = -1;
227 :             x = -x;
228 :         } else {
229 :             sign = 1;
230 :         }
231 : 
232 :         exp = 0;
233 :         while (x != 0) {
234 :             System.arraycopy(mant, mant.length - exp, mant, mant.length - 1 - exp, exp);
235 :             mant[mant.length - 1] = (int) (x % RADIX);
236 :             x /= RADIX;
237 :             exp++;
238 :         }
239 : 
240 :         if (isLongMin) {
241 :             // remove the shift added for Long.MIN_VALUE
242 :             // we know in this case that fixing the last digit is sufficient
243 :             for (int i = 0; i < mant.length - 1; i++) {
244 :                 if (mant[i] != 0) {
245 :                     mant[i]++;
246 :                     break;
247 :                 }
248 :             }
249 :         }
250 :     }"

"331 :     protected Dfp(final DfpField field, final String s) {
332 : 
333 :         // initialize as if 0
334 :         mant = new int[field.getRadixDigits()];
335 :         sign = 1;
336 :         exp = 0;
337 :         nans = FINITE;
338 :         this.field = field;
339 : 
340 :         boolean decimalFound = false;
341 :         final int rsize = 4;   // size of radix in decimal digits
342 :         final int offset = 4;  // Starting offset into Striped
343 :         final char[] striped = new char[getRadixDigits() * rsize + offset * 2];
344 : 
345 :         // Check some special cases
346 :         if (s.equals(POS_INFINITY_STRING)) {
347 :             sign = (byte) 1;
348 :             nans = INFINITE;
349 :             return;
350 :         }
351 : 
352 :         if (s.equals(NEG_INFINITY_STRING)) {
353 :             sign = (byte) -1;
354 :             nans = INFINITE;
355 :             return;
356 :         }
357 : 
358 :         if (s.equals(NAN_STRING)) {
359 :             sign = (byte) 1;
360 :             nans = QNAN;
361 :             return;
362 :         }
363 : 
364 :         // Check for scientific notation
365 :         int p = s.indexOf("e");
366 :         if (p == -1) { // try upper case?
367 :             p = s.indexOf("E");
368 :         }
369 : 
370 :         final String fpdecimal;
371 :         int sciexp = 0;
372 :         if (p != -1) {
373 :             // scientific notation
374 :             fpdecimal = s.substring(0, p);
375 :             String fpexp = s.substring(p+1);
376 :             boolean negative = false;
377 : 
378 :             for (int i=0; i<fpexp.length(); i++)
379 :             {
380 :                 if (fpexp.charAt(i) == '-')
381 :                 {
382 :                     negative = true;
383 :                     continue;
384 :                 }
385 :                 if (fpexp.charAt(i) >= '0' && fpexp.charAt(i) <= '9')
386 :                     sciexp = sciexp * 10 + fpexp.charAt(i) - '0';
387 :             }
388 : 
389 :             if (negative) {
390 :                 sciexp = -sciexp;
391 :             }
392 :         } else {
393 :             // normal case
394 :             fpdecimal = s;
395 :         }
396 : 
397 :         // If there is a minus sign in the number then it is negative
398 :         if (fpdecimal.indexOf("-") !=  -1) {
399 :             sign = -1;
400 :         }
401 : 
402 :         // First off, find all of the leading zeros, trailing zeros, and significant digits
403 :         p = 0;
404 : 
405 :         // Move p to first significant digit
406 :         int decimalPos = 0;
407 :         for (;;) {
408 :             if (fpdecimal.charAt(p) >= '1' && fpdecimal.charAt(p) <= '9') {
409 :                 break;
410 :             }
411 : 
412 :             if (decimalFound && fpdecimal.charAt(p) == '0') {
413 :                 decimalPos--;
414 :             }
415 : 
416 :             if (fpdecimal.charAt(p) == '.') {
417 :                 decimalFound = true;
418 :             }
419 : 
420 :             p++;
421 : 
422 :             if (p == fpdecimal.length()) {
423 :                 break;
424 :             }
425 :         }
426 : 
427 :         // Copy the string onto Stripped
428 :         int q = offset;
429 :         striped[0] = '0';
430 :         striped[1] = '0';
431 :         striped[2] = '0';
432 :         striped[3] = '0';
433 :         int significantDigits=0;
434 :         for(;;) {
435 :             if (p == (fpdecimal.length())) {
436 :                 break;
437 :             }
438 : 
439 :             // Don't want to run pass the end of the array
440 :             if (q == mant.length*rsize+offset+1) {
441 :                 break;
442 :             }
443 : 
444 :             if (fpdecimal.charAt(p) == '.') {
445 :                 decimalFound = true;
446 :                 decimalPos = significantDigits;
447 :                 p++;
448 :                 continue;
449 :             }
450 : 
451 :             if (fpdecimal.charAt(p) < '0' || fpdecimal.charAt(p) > '9') {
452 :                 p++;
453 :                 continue;
454 :             }
455 : 
456 :             striped[q] = fpdecimal.charAt(p);
457 :             q++;
458 :             p++;
459 :             significantDigits++;
460 :         }
461 : 
462 : 
463 :         // If the decimal point has been found then get rid of trailing zeros.
464 :         if (decimalFound && q != offset) {
465 :             for (;;) {
466 :                 q--;
467 :                 if (q == offset) {
468 :                     break;
469 :                 }
470 :                 if (striped[q] == '0') {
471 :                     significantDigits--;
472 :                 } else {
473 :                     break;
474 :                 }
475 :             }
476 :         }
477 : 
478 :         // special case of numbers like "0.00000"
479 :         if (decimalFound && significantDigits == 0) {
480 :             decimalPos = 0;
481 :         }
482 : 
483 :         // Implicit decimal point at end of number if not present
484 :         if (!decimalFound) {
485 :             decimalPos = q-offset;
486 :         }
487 : 
488 :         // Find the number of significant trailing zeros
489 :         q = offset;  // set q to point to first sig digit
490 :         p = significantDigits-1+offset;
491 : 
492 :         int trailingZeros = 0;
493 :         while (p > q) {
494 :             if (striped[p] != '0') {
495 :                 break;
496 :             }
497 :             trailingZeros++;
498 :             p--;
499 :         }
500 : 
501 :         // Make sure the decimal is on a mod 10000 boundary
502 :         int i = ((rsize * 100) - decimalPos - sciexp % rsize) % rsize;
503 :         q -= i;
504 :         decimalPos += i;
505 : 
506 :         // Make the mantissa length right by adding zeros at the end if necessary
507 :         while ((p - q) < (mant.length * rsize)) {
508 :             for (i = 0; i < rsize; i++) {
509 :                 striped[++p] = '0';
510 :             }
511 :         }
512 : 
513 :         // Ok, now we know how many trailing zeros there are,
514 :         // and where the least significant digit is
515 :         for (i = mant.length - 1; i >= 0; i--) {
516 :             mant[i] = (striped[q]   - '0') * 1000 +
517 :                       (striped[q+1] - '0') * 100  +
518 :                       (striped[q+2] - '0') * 10   +
519 :                       (striped[q+3] - '0');
520 :             q += 4;
521 :         }
522 : 
523 : 
524 :         exp = (decimalPos+sciexp) / rsize;
525 : 
526 :         if (q < striped.length) {
527 :             // Is there possible another digit?
528 :             round((striped[q] - '0')*1000);
529 :         }
530 : 
531 :     }"

